1	//! What the experimental TypeScript checker backend hands back, and how it merges over the structural result.
2	//!
3	//! The backend (`caliper-docgen-semantic`) owns the process, the protocol and the checker walk; this module owns only
4	//! the result shape and the merge rules of `docs/type-checker-integration.md`, so `crates/core` stays free of I/O.
5	
6	use std::collections::BTreeMap;
7	use std::hash::{Hash, Hasher};
8	use std::sync::{Arc, Mutex};
9	
10	use camino::Utf8PathBuf;
11	use rustc_hash::{FxHashMap, FxHasher};
12	
13	mod order;
14	
15	use crate::types::collected::ComponentExport;
16	use crate::types::diagnostic::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
17	use crate::types::output::{
18	    ComponentEntry, ExtractionOutput, OpaqueDetail, OpaqueReason, ParsedProp, PropType, TRUNCATED_KIND,
19	};
20	
21	/// The type of a name the checker could not resolve (an import that does not resolve, a name declared nowhere), which
22	/// the checker answers with its error type: an `any` that is not a written `any`. It is `opaque` with the reason
23	/// `unresolvableImport`, so the prop carries `degradedBy`, and `written` is the name as the source writes it, which is
24	/// also what the reason names (the checker does not say which module specifier was behind it).
25	pub fn unresolved_type(written: impl Into<String>) -> PropType {
26	    let written = written.into();
27	    OpaqueDetail::new(written.clone(), OpaqueReason::UnresolvableImport { specifier: written })
28	}
29	
30	/// A type the checker holds that PropType has no shape for: a conditional or indexed access type it could not resolve
31	/// (its parameters are still open), `keyof T`. It is `opaque` with `reason`, so the prop carries `degradedBy`, and
32	/// `raw` is how the checker prints it.
33	pub fn degraded_type(raw: impl Into<String>, reason: OpaqueReason) -> PropType {
34	    OpaqueDetail::new(raw, reason)
35	}
36	
37	/// One prop as the checker reports it.
38	#[derive(Debug, Clone, PartialEq)]
39	pub struct SemanticProp {
40	    /// The prop's name as written in the props type.
41	    pub name: String,
42	    /// The type the checker computed for it, in the same shape the structural resolver produces.
43	    pub prop_type: PropType,
44	    /// Whether the checker found the prop non-optional.
45	    pub required: bool,
46	    /// The prop's JSDoc description, empty when it has none; the merge then keeps the structural description.
47	    pub description: String,
48	    /// Declared by `@types/react` (`children`, `aria-*`, handlers, `className`): not the component's own prop.
49	    pub react_declared: bool,
50	}
51	
52	impl SemanticProp {
53	    fn structural_hash(&self) -> u64 {
54	        let mut hasher = FxHasher::default();
55	        self.name.hash(&mut hasher);
56	        self.required.hash(&mut hasher);
57	        self.react_declared.hash(&mut hasher);
58	        self.description.hash(&mut hasher);
59	        self.prop_type.structural_hash(&mut hasher);
60	        hasher.finish()
61	    }
62	}
63	
64	/// Shares identical props between components, as the structural resolver does: a design system's components repeat
65	/// the same few hundred props, and Chakra's 600 components would otherwise hold 470,000 copies.
66	#[derive(Debug, Default)]
67	pub struct PropInterner {
68	    by_hash: Mutex<FxHashMap<u64, Vec<Arc<SemanticProp>>>>,
69	}
70	
71	impl PropInterner {
72	    /// The one shared copy of `prop`: an equal prop interned earlier, or `prop` itself the first time. If the internal
73	    /// lock is poisoned it returns `prop` unshared rather than failing.
74	    pub fn share(&self, prop: SemanticProp) -> Arc<SemanticProp> {
75	        let hash = prop.structural_hash();
76	        let Ok(mut by_hash) = self.by_hash.lock() else { return Arc::new(prop) };
77	        let bucket = by_hash.entry(hash).or_default();
78	        if let Some(existing) = bucket.iter().find(|existing| ***existing == prop) {
79	            return existing.clone();
80	        }
81	        let shared = Arc::new(prop);
82	        bucket.push(shared.clone());
83	        shared
84	    }
85	}
86	
87	/// One component the checker answered for.
88	#[derive(Debug, Clone, PartialEq)]
89	pub struct SemanticComponent {
90	    /// The output key of the [`SemanticTarget`] this answers: the entry to merge into.
91	    pub key: String,
92	    /// Declared props in declaration order, with the `@types/react` ones the request asked for.
93	    pub props: Vec<Arc<SemanticProp>>,
94	}
95	
96	/// A component the backend left to the structural result, and why.
97	#[derive(Debug, Clone, PartialEq, Eq)]
98	pub struct SemanticFallback {
99	    /// The output key of the [`SemanticTarget`] this answers.
100	    pub key: String,
101	    /// Why the checker did not answer, for example that the component is not exported by its module. The merge groups
102	    /// components by this text into one warning.
103	    pub reason: String,
104	}
105	
106	/// The backend's answer for a run. A backend that could not start returns no components and one diagnostic, never an
107	/// error: the structural result is always a complete answer on its own.
108	#[derive(Debug, Clone, Default, PartialEq)]
109	pub struct SemanticOutcome {
110	    /// The components the checker answered for; each replaces the props of the structural entry it names.
111	    pub components: Vec<SemanticComponent>,
112	    /// The requested components the checker left to the structural result, each with its reason.
113	    pub fallbacks: Vec<SemanticFallback>,
114	    /// What the backend itself reports (it could not start, it timed out); merged into the output's diagnostics.
115	    pub diagnostics: Vec<Diagnostic>,
116	}
117	
118	/// A component the checker may be asked about.
119	#[derive(Debug, Clone, PartialEq, Eq)]
120	pub struct SemanticTarget {
121	    /// The component's output key. Its answer, or its fallback, carries it back, and the merge finds the entry by it:
122	    /// never by file and display name, which two components can share.
123	    pub key: String,
124	    /// The file that declares the component.
125	    pub file_path: Utf8PathBuf,
126	    /// The component's display name, for messages; the checker does not look the component up by it.
127	    pub display_name: String,
128	    /// How the module exports the component ([`ComponentEntry::exports`]): the checker asks for it by exactly these.
129	    /// It answers only for exported components and reports the rest as fallbacks.
130	    pub exports: Vec<ComponentExport>,
131	    /// Props the structural pass already has a description for. The checker is not asked for those: it is 65% of
132	    /// the requests on Mantine, and the merge keeps the structural description when the checker's is empty.
133	    pub described: rustc_hash::FxHashSet<String>,
134	    /// Which props `@types/react` declares the checker reports: `None` for all of them, else only these names. The
135	    /// session decides from `htmlAttributes` (`react_types::react_props_wanted`); the checker never filters by itself.
136	    pub react_wanted: Option<rustc_hash::FxHashSet<String>>,
137	}
138	
139	/// A checker that answers for components as they are asked about, for a long-lived session.
140	///
141	/// `request` never blocks: it queues the targets and returns the receiver that yields the outcome once the checker
142	/// has it, so a caller can wait a bounded time and take the structural answer when the checker is slower.
143	pub trait SemanticProvider: Send + Sync {
144	    /// Queues `targets` for the checker and returns at once with the receiver that will yield their
145	    /// [`SemanticOutcome`].
146	    fn request(&self, targets: Vec<SemanticTarget>) -> std::sync::mpsc::Receiver<SemanticOutcome>;
147	
148	    /// Tells the checker that files changed on disk, before any request that may read them is queued. A checker that
149	    /// keeps what it read (a warm `tsc` holding a snapshot, ADR 0026) reads them again; one that reads every file
150	    /// afresh for each request needs nothing, which is the default.
151	    fn changed(&self, _change: SourceChange) {}
152	}
153	
154	/// What changed on disk, as a session tells its checker ([`SemanticProvider::changed`]).
155	#[derive(Debug, Clone, PartialEq, Eq)]
156	pub enum SourceChange {
157	    /// These files were edited, created or deleted.
158	    Files(Vec<Utf8PathBuf>),
159	    /// Anything may have changed: the session extracted everything again (a resolution config changed, or it started).
160	    Everything,
161	}
162	
163	impl SemanticOutcome {
164	    /// An outcome for a backend that did nothing: the structural result stands, for this reason.
165	    pub fn unavailable(reason: impl Into<String>) -> Self {
166	        let diagnostic = Diagnostic::new(
167	            DiagnosticSeverity::Warning,
168	            DiagnosticCode::SemanticBackend,
169	            format!("TypeScript checker backend unavailable: {}", reason.into()),
170	        )
171	        .with_help(
172	            "The structural result is used instead. Install `typescript@beta` (7.1) or `tsrs`, or pass `--tsc-path`.",
173	        );
174	        Self { diagnostics: vec![diagnostic], ..Self::default() }
175	    }
176	}
177	
178	/// Replaces `entry`'s props with the checker's, keeping what only the structural pass has (a default value, tags,
179	/// `parent`, `declarations`, and a description when the checker has none). A prop whose type the checker could not
180	/// read keeps its structural type, marked (see [`merge_semantic_props`]). `shared` interns identical props across the
181	/// components of one merge. Returns how many props kept their structural type that way.
182	pub fn apply_semantic_props(
183	    entry: &mut ComponentEntry,
184	    semantic: &SemanticComponent,
185	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
186	) -> usize {
187	    // The whole-project merge replaces the props and leaves `@types/react`'s to the inheritance layers.
188	    replace_props(entry, semantic.props.iter().filter(|prop| !prop.react_declared), Unanswered::Drop, shared).unread
189	}
190	
191	/// How a merge went for one component.
192	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
193	pub struct MergedProps {
194	    /// Structural props the checker did not return, kept as the structural pass resolved them.
195	    pub kept: usize,
196	    /// Props the checker returned with a type it could not read (an `opaque` part: an import that does not resolve, a
197	    /// conditional type it left open), where the structural pass read the type in full. They keep the structural type,
198	    /// and their `degradedBy` also lists what the checker could not read.
199	    pub unread: usize,
200	}
201	
202	/// Merges the checker's `props` into `entry` by name: the checker's type, optionality and description win where both
203	/// have a prop, and every structural prop the checker did not return stays as the structural pass resolved it. A prop
204	/// whose checker type holds an `opaque` part, where the structural type holds none, keeps the structural type and adds
205	/// the checker's reasons to its `degradedBy`: the checker's answer there is a placeholder, and the structural one is
206	/// not confirmed, so it is marked. A type the checker only cut at a limit (`truncated`) is still its answer.
207	pub fn merge_semantic_props<'a>(
208	    entry: &mut ComponentEntry,
209	    props: impl Iterator<Item = &'a Arc<SemanticProp>>,
210	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
211	) -> MergedProps {
212	    replace_props(entry, props, Unanswered::Keep, shared)
213	}
214	
215	/// The kinds of what the checker could not read in `checker`, when the structural type `structural` read everything:
216	/// then the structural type is kept and marked with them. Empty when the checker's type is its answer.
217	fn unread_by_checker(checker: &PropType, structural: &PropType) -> Vec<&'static str> {
218	    let unread: Vec<&'static str> = checker.degraded_by().into_iter().filter(|kind| *kind != TRUNCATED_KIND).collect();
219	    if unread.is_empty() || structural.degraded_by().iter().any(|kind| *kind != TRUNCATED_KIND) {
220	        return Vec::new();
221	    }
222	    unread
223	}
224	
225	/// The one diagnostic for the props of `affects` that kept their structural type because the checker could not read it
226	/// ([`MergedProps::unread`]); each such prop says why in its `degradedBy`.
227	pub(crate) fn unread_diagnostic(props: usize, affects: Vec<String>) -> Diagnostic {
228	    let mut diagnostic = Diagnostic::new(
229	        DiagnosticSeverity::Info,
230	        DiagnosticCode::SemanticBackend,
231	        format!(
232	            "{props} prop(s) of {} component(s) keep their structural type: the TypeScript checker could not read it, \
233	             and their degradedBy says what it could not read",
234	            affects.len()
235	        ),
236	    );
237	    diagnostic.affects = affects;
238	    diagnostic
239	}
240	
241	/// What a merge does with a structural prop the checker did not return.
242	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
243	enum Unanswered {
244	    /// The checker decides which props exist, as in the whole-project merge: the structural prop is dropped.
245	    Drop,
246	    /// The checker's props are merged by name, as in a session's merge: the structural prop stays as resolved.
247	    Keep,
248	}
249	
250	fn replace_props<'a>(
251	    entry: &mut ComponentEntry,
252	    props_in: impl Iterator<Item = &'a Arc<SemanticProp>>,
253	    unanswered: Unanswered,
254	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
255	) -> MergedProps {
256	    let mut props: BTreeMap<String, Arc<ParsedProp>> = BTreeMap::new();
257	    let mut unread = 0;
258	    for prop in props_in {
259	        let structural = entry.props.get(&prop.name);
260	        let description = if prop.description.is_empty() {
261	            structural.map(|s| s.description.clone()).unwrap_or_default()
262	        } else {
263	            prop.description.clone()
264	        };
265	        let unread_kinds = structural.map(|s| unread_by_checker(&prop.prop_type, &s.prop_type)).unwrap_or_default();
266	        // The checker sorts a union's members; where the structural pass resolved the same union, its order is the
267	        // declared one.
268	        let prop_type = match structural {
269	            Some(structural) if !unread_kinds.is_empty() => structural.prop_type.clone(),
270	            Some(structural) => order::in_declared_order(prop.prop_type.clone(), &structural.prop_type),
271	            None => prop.prop_type.clone(),
272	        };
273	        unread += usize::from(!unread_kinds.is_empty());
274	        let merged = ParsedProp::new(
275	            prop.name.clone(),
276	            prop_type,
277	            prop.required,
278	            structural.and_then(|s| s.default_value.clone()),
279	            description,
280	            structural.map(|s| s.tags.clone()).unwrap_or_default(),
281	            structural.and_then(|s| s.parent.clone()),
282	            structural.map(|s| s.declarations.clone()).unwrap_or_default(),
283	        )
284	        .degraded_also_by(&unread_kinds);
285	        let mut hasher = FxHasher::default();
286	        merged.structural_hash(&mut hasher);
287	        let bucket = shared.entry(hasher.finish()).or_default();
288	        let merged = match bucket.iter().find(|existing| ***existing == merged) {
289	            Some(existing) => existing.clone(),
290	            None => {
291	                let merged = Arc::new(merged);
292	                bucket.push(merged.clone());
293	                merged
294	            }
295	        };
296	        props.insert(prop.name.clone(), merged);
297	    }
298	    let mut kept = 0;
299	    if unanswered == Unanswered::Keep {
300	        for (name, structural) in &entry.props {
301	            if !props.contains_key(name) {
302	                props.insert(name.clone(), structural.clone());
303	                kept += 1;
304	            }
305	        }
306	    }
307	    entry.props = props;
308	    MergedProps { kept, unread }
309	}
310	
311	/// Merge the checker's props over `output`, component by component.
312	///
313	/// Per `docs/type-checker-integration.md`: the checker decides which props exist, their types and whether they are
314	/// required; a description comes from the checker, else the structural pass; a default value stays structural (the
315	/// checker has no initializer for a destructured parameter); `parent` and `declarations` stay with the structural
316	/// prop of the same name. Inheritance layers and curated inherited props stay structural. Components the checker did
317	/// not answer for keep their structural result untouched.
318	///
319	/// Records provenance as `Info` diagnostics whose `affects` lists the output keys, so the canonical JSON gains no
320	/// field: one for the components the checker resolved, one per fallback reason.
321	pub fn merge_semantic(output: &mut ExtractionOutput, outcome: SemanticOutcome) {
322	    let SemanticOutcome { components, fallbacks, diagnostics } = outcome;
323	    let mut merged_keys = Vec::new();
324	    let (mut unread_keys, mut unread_props) = (Vec::new(), 0);
325	    let mut shared: FxHashMap<u64, Vec<Arc<ParsedProp>>> = FxHashMap::default();
326	    for semantic in components {
327	        let Some(entry) = output.components.get_mut(&semantic.key) else { continue };
328	        let unread = apply_semantic_props(entry, &semantic, &mut shared);
329	        if unread > 0 {
330	            unread_props += unread;
331	            unread_keys.push(semantic.key.clone());
332	        }
333	        merged_keys.push(semantic.key);
334	    }
335	    output.diagnostics.extend(diagnostics);
336	
337	    // A structural diagnostic about a prop the checker now answers for would be stale; the resolved component keeps
338	    // none of its degrade diagnostics.
339	    if !merged_keys.is_empty() {
340	        output.diagnostics.retain(|diagnostic| {
341	            let degrade = matches!(
342	                diagnostic.code,
343	                DiagnosticCode::OpaqueType | DiagnosticCode::MaxDepthExceeded | DiagnosticCode::CircularReference
344	            );
345	            !(degrade
346	                && !diagnostic.affects.is_empty()
347	                && diagnostic.affects.iter().all(|key| merged_keys.contains(key)))
348	        });
349	        merged_keys.sort();
350	        let mut provenance = Diagnostic::new(
351	            DiagnosticSeverity::Info,
352	            DiagnosticCode::SemanticBackend,
353	            format!("{} component(s) resolved by the TypeScript checker", merged_keys.len()),
354	        );
355	        provenance.affects = merged_keys;
356	        output.diagnostics.push(provenance);
357	    }
358	    if !unread_keys.is_empty() {
359	        unread_keys.sort();
360	        output.diagnostics.push(unread_diagnostic(unread_props, unread_keys));
361	    }
362	
363	    let mut by_reason: BTreeMap<String, Vec<String>> = BTreeMap::new();
364	    for SemanticFallback { key, reason } in fallbacks {
365	        if output.components.contains_key(&key) {
366	            by_reason.entry(reason).or_default().push(key);
367	        }
368	    }
369	    for (reason, mut keys) in by_reason {
370	        keys.sort();
371	        let mut diagnostic = Diagnostic::new(
372	            DiagnosticSeverity::Info,
373	            DiagnosticCode::SemanticBackend,
374	            format!("{} component(s) kept their structural result: {reason}", keys.len()),
375	        );
376	        diagnostic.affects = keys;
377	        output.diagnostics.push(diagnostic);
378	    }
379	}
380	
