1	//! Typed calls over one `tsc --api` session. Wire shapes are the ones the official 7.1 client sends (traced against
2	//! `7.1.0-beta`); a method this module does not name is not used.
3	
4	use std::collections::BTreeMap;
5	use std::sync::{Arc, Mutex};
6	use std::time::Duration;
7	
8	use caliper_docgen_tsc_client::{Client, TscClientError};
9	use serde::Deserialize;
10	use serde::de::DeserializeOwned;
11	use serde_json::value::RawValue;
12	use serde_json::{Value, json};
13	
14	/// Why a call failed, split by whether the rest of the run can go on.
15	#[derive(Debug)]
16	pub(crate) enum CallError {
17	    /// The session is gone or stuck: every later call would fail the same way.
18	    Fatal(String),
19	    /// The checker rejected this one call; other components may still resolve.
20	    Rejected(String),
21	}
22	
23	impl std::fmt::Display for CallError {
24	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
25	        match self {
26	            CallError::Fatal(message) | CallError::Rejected(message) => f.write_str(message),
27	        }
28	    }
29	}
30	
31	fn classify(error: TscClientError) -> CallError {
32	    match error {
33	        TscClientError::RpcError { message, .. } => CallError::Rejected(message),
34	        other => CallError::Fatal(other.to_string()),
35	    }
36	}
37	
38	#[derive(Debug, Clone, Deserialize)]
39	#[serde(rename_all = "camelCase")]
40	pub(crate) struct SymbolInfo {
41	    /// The full reference the checker wants back to name this symbol; opaque to us.
42	    pub reference: Value,
43	    /// The name the source writes: the checker's escaped name with the escaping removed (see
44	    /// [`unescape_leading_underscores`]).
45	    #[serde(deserialize_with = "unescaped_name")]
46	    pub name: String,
47	    pub flags: u64,
48	    #[serde(default)]
49	    pub declarations: Vec<String>,
50	}
51	
52	/// A symbol as another response embeds it: the id, and the node id of the file that owns it. The full symbol is one
53	/// call away (`getSymbolOfType`, `getAliasSymbolOfType`).
54	#[derive(Debug, Clone, PartialEq, Eq, Hash, Deserialize)]
55	pub(crate) struct CompactSymbol {
56	    pub id: u64,
57	    #[serde(default)]
58	    pub file: Option<String>,
59	}
60	
61	/// The checker keeps a symbol's name in an escaped form: a name that starts with two underscores gets a third
62	/// (`escapeLeadingUnderscores`), so that it cannot collide with its own internal names such as `__call`. The source
63	/// writes `__size`, the checker answers `___size`. A name with fewer than three leading underscores is unchanged, and
64	/// so are the internal names, which start with exactly two.
65	pub(crate) fn unescape_leading_underscores(name: &str) -> &str {
66	    if name.starts_with("___") { name.strip_prefix('_').unwrap_or(name) } else { name }
67	}
68	
69	fn unescaped_name<'de, D: serde::Deserializer<'de>>(deserializer: D) -> Result<String, D::Error> {
70	    let name = String::deserialize(deserializer)?;
71	    Ok(unescape_leading_underscores(&name).to_string())
72	}
73	
74	#[derive(Debug, Clone, Deserialize)]
75	#[serde(rename_all = "camelCase")]
76	pub(crate) struct TypeInfo {
77	    pub id: u64,
78	    pub flags: u64,
79	    #[serde(default)]
80	    pub object_flags: u64,
81	    #[serde(default)]
82	    pub value: Option<Value>,
83	    #[serde(default)]
84	    pub is_tuple_type: bool,
85	    /// The checker's name for an intrinsic type (`"any"`, `"string"`, `"error"`). It alone tells a written `any` from
86	    /// the error type of an unresolved name: both carry the `Any` flag, and the error type has an id per site.
87	    #[serde(default)]
88	    pub intrinsic_name: Option<String>,
89	    /// `TupleElementFlags` of a tuple type's elements: required 1, optional 2, rest 4, variadic 8.
90	    #[serde(default)]
91	    pub element_flags: Vec<u64>,
92	    /// A tuple type written `readonly [...]`.
93	    #[serde(default)]
94	    pub readonly: bool,
95	    /// One declaration handle per element of a tuple whose elements are labeled, `[head: string]`; empty otherwise.
96	    #[serde(default)]
97	    pub labeled_element_declarations: Vec<String>,
98	    /// The text pieces of a template literal type, around its holes.
99	    #[serde(default)]
100	    pub texts: Vec<String>,
101	    /// The `this` type of a class or interface, which the checker also appends to a reference's type arguments.
102	    #[serde(default)]
103	    pub is_this_type: bool,
104	    /// The symbol that declares an object type; absent for primitives and unions.
105	    #[serde(default)]
106	    pub symbol: Option<CompactSymbol>,
107	    /// The alias this type was written through, `Size` in `type Size = "sm" | "lg"`.
108	    #[serde(default)]
109	    pub alias_symbol: Option<CompactSymbol>,
110	    /// Ids of the alias's type arguments; `Rpc::alias_type_arguments` fetches them.
111	    #[serde(default)]
112	    pub alias_type_arguments: Vec<u64>,
113	}
114	
115	impl TypeInfo {
116	    /// The checker's error type: what a name that does not resolve is typed as.
117	    pub(crate) fn is_error(&self) -> bool {
118	        self.flags & flag::ANY != 0 && self.intrinsic_name.as_deref() == Some("error")
119	    }
120	}
121	
122	#[derive(Debug, Clone, Deserialize)]
123	#[serde(rename_all = "camelCase")]
124	pub(crate) struct SignatureInfo {
125	    pub id: u64,
126	    /// `SignatureFlags`; see [`flag::SIGNATURE_HAS_REST_PARAMETER`].
127	    #[serde(default)]
128	    pub flags: u64,
129	    /// The signature's own type parameters (ids; `Rpc::type_parameters` fetches them).
130	    #[serde(default)]
131	    pub type_parameters: Vec<u64>,
132	    /// One entry per declared parameter, `this` excluded; `Rpc::parameters` fetches them.
133	    #[serde(default)]
134	    pub parameters: Vec<serde::de::IgnoredAny>,
135	}
136	
137	/// What an object type holds, as one batch answers it.
138	pub(crate) struct ObjectMembers {
139	    pub calls: Vec<SignatureInfo>,
140	    pub constructs: Vec<SignatureInfo>,
141	    pub properties: Vec<SymbolInfo>,
142	    pub indexes: Vec<IndexInfo>,
143	}
144	
