1	//! One component's props from the checker: the export's call signature, its first parameter's type, that type's
2	//! properties.
3	
4	use std::sync::Arc;
5	
6	use caliper_docgen_core::types::ComponentExport;
7	use caliper_docgen_core::types::semantic::{PropInterner, SemanticProp};
8	
9	use crate::Target;
10	use crate::convert::{Converter, declared_in, without_undefined};
11	use crate::instantiate::{self, Instantiation};
12	use crate::rpc::{CallError, Rpc, SignatureKind, SymbolInfo, TypeInfo, flag};
13	
14	pub(crate) enum Answer {
15	    Props(Vec<Arc<SemanticProp>>),
16	    /// The component keeps its structural result, for this reason.
17	    Fallback(String),
18	    /// A generic component, whose props are read from an instantiation of it ([`crate::instantiate`]).
19	    Instantiate(Instantiation),
20	}
21	
22	/// What `@types/react` declares (`key`, `ref`, `children` on `PropsWithChildren`, HTML attributes). Reported with the
23	/// flag set when the request asks for the name; what to do with them is the session's policy, not ours.
24	fn is_react_declared(property: &SymbolInfo) -> bool {
25	    property.declarations.iter().any(|declaration| declared_in(declaration).contains("/@types/react/"))
26	}
27	
28	fn fallback(reason: &str) -> Result<Answer, CallError> {
29	    Ok(Answer::Fallback(reason.to_string()))
30	}
31	
32	/// A module as the checker reads it: its own symbol, whose declaration names its file in the checker's spelling, and
33	/// its exports.
34	pub(crate) struct Module {
35	    pub(crate) symbol: SymbolInfo,
36	    pub(crate) exports: Vec<SymbolInfo>,
37	}
38	
39	impl Module {
40	    /// Whether one of `symbol`'s declarations is in this module's file.
41	    fn declares(&self, symbol: &SymbolInfo) -> bool {
42	        let files: Vec<&str> = self.symbol.declarations.iter().map(|declaration| declared_in(declaration)).collect();
43	        symbol.declarations.iter().any(|declaration| files.contains(&declared_in(declaration)))
44	    }
45	}
46	
47	/// The symbol `export` names in `module`: the export of exactly that name, through an alias to what it aliases, then
48	/// each property an attached sub-component is reached through. `Err` says why there is none, or why it is not the
49	/// component the extractor found: one declared in another file.
50	async fn exported_symbol(
51	    rpc: &Rpc,
52	    module: &Module,
53	    export: &ComponentExport,
54	) -> Result<Result<SymbolInfo, String>, CallError> {
55	    let Some(symbol) = module.exports.iter().find(|symbol| symbol.name == export.name) else {
56	        return Ok(Err(format!("the checker finds no export `{}` in its module", export.name)));
57	    };
58	    let mut symbol = if symbol.flags & flag::SYMBOL_ALIAS != 0 {
59	        rpc.aliased_symbol(&symbol.reference).await?
60	    } else {
61	        symbol.clone()
62	    };
63	    for member in &export.members {
64	        let parent = rpc.type_of_symbol(&symbol.reference).await?;
65	        let Some(property) = rpc.properties(parent.id).await?.into_iter().find(|property| property.name == *member)
66	        else {
67	            return Ok(Err(format!("the checker finds no property `{member}` on the export `{}`", export.name)));
68	        };
69	        symbol = property;
70	    }
71	    if !module.declares(&symbol) {
72	        return Ok(Err(format!("the export `{export}` is declared in another file")));
73	    }
74	    Ok(Ok(symbol))
75	}
76	
77	/// The component's symbol: the first export the extractor recorded for it that the checker finds. Never another
78	/// export, such as the module's `default` when `default` is not one of them.
79	async fn component_symbol(
80	    rpc: &Rpc,
81	    module: &Module,
82	    target: &Target,
83	) -> Result<Result<(SymbolInfo, ComponentExport), String>, CallError> {
84	    let mut reasons = Vec::new();
85	    for export in &target.exports {
86	        match exported_symbol(rpc, module, export).await? {
87	            Ok(symbol) => return Ok(Ok((symbol, export.clone()))),
88	            Err(reason) => reasons.push(reason),
89	        }
90	    }
91	    Ok(Err(if reasons.is_empty() { "not exported by its module".to_string() } else { reasons.join("; ") }))
92	}
93	
94	pub(crate) async fn props_of(
95	    rpc: &Rpc,
96	    converter: &Converter,
97	    interner: &PropInterner,
98	    module: &Module,
99	    target: &Target,
100	) -> Result<Answer, CallError> {
101	    let (symbol, export) = match component_symbol(rpc, module, target).await? {
102	        Ok(found) => found,
103	        Err(reason) => return Ok(Answer::Fallback(reason)),
104	    };
105	
106	    let component = rpc.type_of_symbol(&symbol.reference).await?;
107	    let signatures = rpc.signatures(component.id, SignatureKind::Call).await?;
108	    let [signature] = signatures.as_slice() else {
109	        return fallback(if signatures.is_empty() {
110	            "no call signature (class or non-function component)"
111	        } else {
112	            "overloaded call signatures"
113	        });
114	    };
115	    let parameters = rpc.parameters(signature.id).await?;
116	    let Some(first) = parameters.first() else { return fallback("takes no props parameter") };
117	    if let Some(arguments) = instantiate::default_arguments(rpc, signature).await? {
118	        if !export.members.is_empty() {
119	            return fallback("a generic sub-component reached through its parent's property is not instantiated");
120	        }
121	        return Ok(Answer::Instantiate(Instantiation { export: export.name, arguments }));
122	    }
123	
124	    let props_type = rpc.type_of_symbol(&first.reference).await?;
125	    Ok(props_of_type(rpc, converter, interner, &props_type, target).await?.map_or_else(Answer::Fallback, Answer::Props))
126	}
127	
128	/// The props a component's props type holds, or why the component keeps its structural result.
129	pub(crate) async fn props_of_type(
130	    rpc: &Rpc,
131	    converter: &Converter,
132	    interner: &PropInterner,
133	    props_type: &TypeInfo,
134	    target: &Target,
135	) -> Result<Result<Vec<Arc<SemanticProp>>, String>, CallError> {
136	    if props_type.flags & (flag::ANY | flag::UNKNOWN | flag::UNION | flag::TYPE_PARAMETER) != 0 {
137	        return Ok(Err("props type is any, unknown, generic or a union".to_string()));
138	    }
139	
140	    let own: Vec<SymbolInfo> = rpc
141	        .properties(props_type.id)
142	        .await?
143	        .into_iter()
144	        .filter(|property| {
145	            !is_react_declared(property)
146	                || target.react_wanted.as_ref().is_none_or(|wanted| wanted.contains(&property.name))
147	        })
148	        .collect();
149	    let references: Vec<_> = own.iter().map(|property| &property.reference).collect();
150	    let types = if references.is_empty() { Vec::new() } else { rpc.types_of_symbols(&references).await? };
151	
152	    let converted = converter.convert_roots(&types).await?;
153	    let mut props = Vec::with_capacity(own.len());
154	    for (property, prop_type) in own.iter().zip(converted) {
155	        let required = property.flags & flag::SYMBOL_OPTIONAL == 0;
156	        let react_declared = is_react_declared(property);
157	        props.push(interner.share(SemanticProp {
158	            name: property.name.clone(),
159	            prop_type: without_undefined(prop_type, !required),
160	            required,
161	            react_declared,
162	            // React's own descriptions are the structural pass's to give, and fetching one per attribute is a call each.
163	            description: if react_declared || target.described.contains(&property.name) {
164	                String::new()
165	            } else {
166	                rpc.documentation(&property.reference).await?
167	            },
168	        }));
169	    }
170	    Ok(Ok(props))
171	}
172	
173	#[cfg(test)]
174	mod tests {
175	    use super::*;
176	
177	    fn property(declaration: &str) -> SymbolInfo {
178	        SymbolInfo {
179	            reference: serde_json::Value::Null,
180	            name: "x".to_string(),
181	            flags: 4,
182	            declarations: vec![declaration.to_string()],
183	        }
184	    }
185	
186	    #[test]
187	    fn the_declaring_path_is_what_follows_the_node_id_and_position() {
188	        assert_eq!(
189	            declared_in("48.264./proj/node_modules/@types/react/index.d.ts"),
190	            "/proj/node_modules/@types/react/index.d.ts"
191	        );
192	        assert_eq!(declared_in("garbage"), "");
193	    }
194	
195	    #[test]
196	    fn only_properties_declared_in_types_react_are_excluded() {
197	        assert!(is_react_declared(&property("1.2./p/node_modules/@types/react/index.d.ts")));
198	        assert!(!is_react_declared(&property("1.2./p/src/button.tsx")));
199	        assert!(!is_react_declared(&property("1.2./p/node_modules/@chakra-ui/react/dist/index.d.ts")));
200	    }
201	}
