// ─── JSDoc parsing ────────────────────────────────────────────────────────────

pub(super) fn parse_jsdoc_text(raw: &str) -> String {
    let inner = raw.trim_start_matches("/**").trim_end_matches("*/");

    let desc_lines: Vec<&str> = inner
        .lines()
        .map(|l| {
            let l = l.trim();

            l.strip_prefix("* ").or_else(|| l.strip_prefix('*')).unwrap_or(l)
        })
        .take_while(|l| !l.starts_with('@'))
        .collect();

    desc_lines.join("\n").trim().to_owned()
}

pub(super) fn extract_jsdoc_tags(raw: &str) -> BTreeMap<String, String> {
    let inner = raw.trim_start_matches("/**").trim_end_matches("*/");
    let mut tags: BTreeMap<String, String> = BTreeMap::new();
    let mut last_key: Option<String> = None;

    for line in inner.lines() {
        let line = line.trim();
        let line = line.strip_prefix("* ").or_else(|| line.strip_prefix('*')).unwrap_or(line);
        let line = line.trim();

        if let Some(rest) = line.strip_prefix('@') {
            last_key = None;
            let (tag, value) = if let Some(sp) = rest.find(char::is_whitespace) {
                let tag = &rest[..sp];
                let value = rest[sp..].trim();
                (tag, value)
            } else {
                (rest, "")
            };

            // Special handling for @param — store as `param:propName`
            if tag == "param" {
                // Accepts both `@param propName description` and
                // `@param {type} propName description`.
                let value = value.trim_start_matches('{');
                let value =
                    if value.contains('}') { value.split_once('}').map(|x| x.1).unwrap_or("").trim() } else { value };
                if let Some(space) = value.find(char::is_whitespace) {
                    let prop_name = &value[..space];
                    let desc = value[space..].trim();
                    let key = format!("param:{}", prop_name);
                    tags.insert(key.clone(), desc.to_owned());
                    last_key = Some(key);
                } else if !value.is_empty() {
                    let key = format!("param:{}", value);
                    tags.insert(key.clone(), String::new());
                    last_key = Some(key);
                }
            } else {
                tags.insert(tag.to_owned(), value.to_owned());
                last_key = Some(tag.to_owned());
            }
        } else if let Some(text) = last_key.as_ref().and_then(|key| tags.get_mut(key)) {
            // A tag's value runs until the next tag.
            if !line.is_empty() {
                if !text.is_empty() {
                    text.push('\n');
                }
                text.push_str(line);
            }
        }
    }

