133	/// The exported targets by file, in first-seen order, and an outcome that already holds a fallback for each target
134	/// the checker cannot be asked about.
135	fn group_by_file(request: &SemanticRequest) -> (SemanticOutcome, FxHashMap<&Utf8Path, Vec<&Target>>, Vec<&Utf8Path>) {
136	    let mut outcome = SemanticOutcome::default();
137	    let mut by_file: FxHashMap<&Utf8Path, Vec<&Target>> = FxHashMap::default();
138	    let mut order: Vec<&Utf8Path> = Vec::new();
139	    for target in &request.targets {
140	        if target.exports.is_empty() {
141	            outcome.fallbacks.push(fallback_of(target, "not exported by its module"));
142	            continue;
143	        }
144	        let group = by_file.entry(target.file_path.as_path()).or_default();
145	        if group.is_empty() {
146	            order.push(target.file_path.as_path());
147	        }
148	        group.push(target);
149	    }
150	    (outcome, by_file, order)
151	}
152	
153	fn supervisor_config(request: &SemanticRequest) -> Result<SupervisorConfig, String> {
154	    let tsc_path = locate::find_tsc(&request.project_root, request.tsc_path.as_deref())?;
155	    let mut config = SupervisorConfig::new(tsc_path, request.project_root.clone(), request.expected_versions);
156	    config.handshake_timeout = request.request_timeout;
157	    config.extra_env.clone_from(&request.extra_env);
158	    Ok(config)
159	}
160	
161	async fn run(request: SemanticRequest) -> SemanticOutcome {
162	    if request.targets.iter().all(|target| target.exports.is_empty()) {
163	        return group_by_file(&request).0;
164	    }
165	    let config = match supervisor_config(&request) {
166	        Ok(config) => config,
167	        Err(reason) => return SemanticOutcome::unavailable(reason),
168	    };
169	    let supervisor = match Supervisor::spawn(config).await {
170	        Ok(supervisor) => supervisor,
171	        Err(error) => return SemanticOutcome::unavailable(error.to_string()),
172	    };
173	    let outcome = answer_with(&supervisor, &request).await;
174	    supervisor.shutdown().await.ok();
175	    outcome
176	}
177	
178	/// The files of the request's exported targets, in first-seen order: the roots of the program that answers it.
179	fn root_files(request: &SemanticRequest) -> Vec<String> {
180	    group_by_file(request).2.iter().map(|file| file.to_string()).collect()
181	}
182	
183	/// Answers the request's targets with a checker that is already running: one program rooted at their files, released
184	/// once they are answered.
185	async fn answer_with(supervisor: &Supervisor, request: &SemanticRequest) -> SemanticOutcome {
186	    let files = root_files(request);
187	    if files.is_empty() {
188	        return group_by_file(request).0;
189	    }
190	    let started = std::time::Instant::now();
191	    let tsconfig = request.tsconfig.as_ref().map(|path| path.as_str());
192	    let opened =
193	        Rpc::open(supervisor.client(), request.request_timeout, tsconfig, &files, request.record_to.is_some()).await;
194	    let rpc = match opened {
195	        Ok(rpc) => Arc::new(rpc),
196	        Err(error) => return SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")),
197	    };
198	    tracing::debug!(program_ms = started.elapsed().as_millis() as u64, "semantic program built");
199	    let answered = answer_on(&rpc, request, &files).await;
200	    rpc.release().await;
201	    answered.unwrap_or_else(|error| SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")))
202	}
203	
204	/// Answers the request's targets on a snapshot whose program is rooted at `files` ([`root_files`]). The snapshot is
205	/// left as it is, for the caller to keep or release.
206	async fn answer_on(rpc: &Arc<Rpc>, request: &SemanticRequest, files: &[String]) -> Result<SemanticOutcome, CallError> {
207	    let (mut outcome, by_file, order) = group_by_file(request);
208	    let mut answered = session(rpc, request, files, &by_file, &order).await?;
209	    outcome.components.append(&mut answered.components);
210	    outcome.fallbacks.append(&mut answered.fallbacks);
211	    Ok(outcome)
212	}
213	
214	async fn session(
215	    rpc: &Arc<Rpc>,
216	    request: &SemanticRequest,
217	    files: &[String],
218	    by_file: &FxHashMap<&Utf8Path, Vec<&Target>>,
219	    order: &[&Utf8Path],
220	) -> Result<SemanticOutcome, CallError> {
221	    let started = std::time::Instant::now();
222	    let converter = Converter::new(rpc.clone(), request.reverse_queries);
223	    let limit = Arc::new(Semaphore::new(FILES_IN_FLIGHT));
224	    let interner = Arc::new(PropInterner::default());
225	
226	    let mut tasks = JoinSet::new();
227	    for file in order {
228	        let targets: Vec<Target> = by_file.get(file).into_iter().flatten().map(|target| (*target).clone()).collect();
229	        let (rpc, converter, limit, interner) = (rpc.clone(), converter.clone(), limit.clone(), interner.clone());
230	        tasks.spawn(async move {
231	            let _permit = limit.acquire().await;
232	            answer_file(&rpc, &converter, &interner, targets).await
233	        });
234	    }
235	
236	    let mut outcome = SemanticOutcome::default();
237	    let mut generic = Vec::new();
238	    let mut failure = None;
239	    while let Some(joined) = tasks.join_next().await {
240	        match joined {
241	            Ok(Ok((mut answered, mut instantiations))) => {
242	                outcome.components.append(&mut answered.components);
243	                outcome.fallbacks.append(&mut answered.fallbacks);
244	                generic.append(&mut instantiations);
245	            }
246	            Ok(Err(error)) => {
247	                failure = Some(error);
248	                tasks.abort_all();
249	            }
250	            // A panic inside a worker must not silently leave its components structural.
251	            Err(joined) if joined.is_panic() => {
252	                failure = Some(CallError::Fatal("a worker panicked".to_string()));
253	                tasks.abort_all();
254	            }
255	            // A cancelled task is one this loop aborted after a failure.
256	            Err(_cancelled) => {}
257	        }
258	    }
259	    if let Some(error) = failure {
260	        return Err(error);
261	    }
262	    if !generic.is_empty() {
263	        let mut instantiated =
264	            instantiate::answer(rpc, files, &request.project_root, &interner, request.reverse_queries, generic).await?;
265	        outcome.components.append(&mut instantiated.components);
266	        outcome.fallbacks.append(&mut instantiated.fallbacks);
267	    }
268	
269	    if let (Some(path), Some(recording)) = (&request.record_to, rpc.recording())
270	        && let Ok(json) = serde_json::to_string_pretty(&recording)
271	        && let Err(error) = std::fs::write(path, json)
272	    {
273	        tracing::warn!("could not write the recording to {path}: {error}");
274	    }
275	    tracing::debug!(
276	        requests = ?rpc.calls(),
277	        files = files.len(),
278	        type_memo = ?converter.memo_stats(),
279	        total_ms = started.elapsed().as_millis() as u64,
280	        "semantic backend finished"
281	    );
282	    outcome.components.sort_by(|a, b| a.key.cmp(&b.key));
283	    outcome.fallbacks.sort_by(|a, b| a.key.cmp(&b.key));
284	    Ok(outcome)
285	}
286	
287	fn fallback_of(target: &Target, reason: &str) -> SemanticFallback {
288	    SemanticFallback { key: target.key.clone(), reason: reason.to_string() }
289	}
290	
291	/// A fatal error aborts the run; a call the checker rejected only sends that component to its structural result. The
292	/// generic components come back apart, to be answered from their instantiations once every file is done.
293	async fn answer_file(
294	    rpc: &Rpc,
295	    converter: &Converter,
296	    interner: &PropInterner,
297	    targets: Vec<Target>,
298	) -> Result<(SemanticOutcome, Vec<(Target, Instantiation)>), CallError> {
299	    let mut outcome = SemanticOutcome::default();
300	    let mut generic = Vec::new();
301	    let Some(first) = targets.first() else { return Ok((outcome, generic)) };
302	    let module = match module_exports(rpc, first.file_path.as_str()).await {
303	        Ok(Some(module)) => module,
304	        Ok(None) | Err(CallError::Rejected(_)) => {
305	            outcome
306	                .fallbacks
307	                .extend(targets.iter().map(|target| fallback_of(target, "not part of the checker's program")));
308	            return Ok((outcome, generic));
309	        }
310	        Err(fatal) => return Err(fatal),
311	    };
312	
313	    for target in &targets {
314	        let requests = Arc::new(AtomicU64::new(0));
315	        let started = std::time::Instant::now();
316	        let answered =
317	            REQUESTS.scope(requests.clone(), component::props_of(rpc, converter, interner, &module, target)).await;
318	        tracing::debug!(
319	            component = %target.display_name,
320	            requests = requests.load(Ordering::Relaxed),
321	            ms = started.elapsed().as_millis() as u64,
322	            "semantic component answered"
323	        );
324	        match answered {
325	            Ok(Answer::Props(props)) => outcome.components.push(SemanticComponent { key: target.key.clone(), props }),
326	            Ok(Answer::Fallback(reason)) => outcome.fallbacks.push(fallback_of(target, &reason)),
327	            Ok(Answer::Instantiate(instantiation)) => generic.push((target.clone(), instantiation)),
328	            Err(CallError::Rejected(message)) => {
329	                outcome.fallbacks.push(fallback_of(target, &format!("the checker rejected a request: {message}")));
330	            }
331	            Err(fatal) => return Err(fatal),
332	        }
333	    }
334	    Ok((outcome, generic))
335	}
336	
337	/// The module `file` is, as the checker reads it, with its exports; `None` when the file is not in its program.
338	async fn module_exports(rpc: &Rpc, file: &str) -> Result<Option<component::Module>, CallError> {
339	    let Some(symbol) = rpc.source_file_symbol(file).await? else { return Ok(None) };
340	    let exports = rpc.exports_of_module(&symbol.reference).await?;
341	    Ok(Some(component::Module { symbol, exports }))
342	}
