const UTILITIES: [&str; 5] = ["Omit", "Pick", "Partial", "Required", "Readonly"];

/// What a descent found at [`Converter::enter`].
enum Gate<T> {
    /// The type is not expanded: it is a back-reference, or a cap cut it.
