input.content:
//! Where each of a component's props is declared and what its JSDoc says, from the checker: the interface each of its
//! declarations sits in (`parent`, `declarations`), its description and its tags.
//!
//! A property symbol names the symbol it is a member of (`parent`); one a mapped type or an intersection made
//! (`Omit<Base, "x">`, `A & B`) names none, and its declarations are asked for the symbols they declare, whose parent
//! is the interface that wrote them. A parent is asked for its name once per snapshot. A declaration names its file the
//! way the checker keys files, lower-cased where file names are not case-sensitive; the file is reported as the program
//! read it (`getSourceFileNames`), so `parent.fileName` is the path on disk, as the structural pass reports it.

use std::collections::BTreeMap;
use std::sync::Mutex;

use caliper_docgen_core::types::PropParent;
use rustc_hash::FxHashMap;
use serde_json::{Value, json};
use tokio::sync::OnceCell;

use crate::convert::declared_in;
use crate::rpc::{CallError, CompactSymbol, JsDocTag, Rpc, SymbolInfo, decode, flag};

/// One prop to look up, and which of its JSDoc to ask for.
pub(crate) struct Asked<'a> {
    pub(crate) property: &'a SymbolInfo,
    /// Ask for its description: the structural pass has none for it.
    pub(crate) description: bool,
    /// Ask for its tags.
    pub(crate) tags: bool,
}

/// What the checker says about where one prop is declared.
#[derive(Debug, Default)]
pub(crate) struct Declared {
    /// Empty when not asked for, or when it has none.
    pub(crate) description: String,
    /// Empty when not asked for, or when it has none.
    pub(crate) tags: BTreeMap<String, String>,
    pub(crate) parent: Option<PropParent>,
    pub(crate) declarations: Vec<PropParent>,
}

/// What one snapshot's answers about declarations are kept as: they do not change inside it.
#[derive(Debug, Default)]
pub(crate) struct Memo {
    /// A parent symbol's name when it is an interface, else `None` (a type literal, a class, a module).
    parents: Mutex<FxHashMap<CompactSymbol, Option<String>>>,
    /// The program's files by the path a declaration names: the path itself, and lower-cased.
    files: OnceCell<FxHashMap<String, String>>,
}

/// The request a batch holds for one answer, so the answer is read in the shape its method returns.
enum Pending {
    Description(usize),
    Tags(usize),
    /// The symbol declaration `.1` of prop `.0` declares.
    Declares(usize, usize),
}

/// The declarations, description and tags of every prop of `asked`, in its order: one round trip for what each prop
/// needs asked, one for the parents not seen before in this snapshot, and one per snapshot for its files.
pub(crate) async fn declared(rpc: &Rpc, memo: &Memo, asked: &[Asked<'_>]) -> Result<Vec<Declared>, CallError> {
    let mut requests: Vec<(&str, Value)> = Vec::new();
    let mut pending = Vec::new();
    // The symbol each declaration declares, with the reference that names it: the property itself when it has a parent
    // and one declaration.
    let mut declares: Vec<Vec<Option<(Option<CompactSymbol>, Value)>>> = Vec::with_capacity(asked.len());
    for (index, prop) in asked.iter().enumerate() {
        let property = prop.property;
        if prop.description {
            requests.push(("getDocumentationComment", json!({ "symbol": property.reference })));
            pending.push(Pending::Description(index));
        }
        if prop.tags {
            requests.push(("getJsDocTags", json!({ "symbol": property.reference })));
            pending.push(Pending::Tags(index));
        }
        match (&property.parent, property.declarations.as_slice()) {
            (Some(parent), [_]) => declares.push(vec![Some((Some(parent.clone()), property.reference.clone()))]),
            (_, declarations) => {
                for (position, declaration) in declarations.iter().enumerate() {
                    requests.push(("getSymbolOfDeclarationForChecker", json!({ "location": declaration })));
                    pending.push(Pending::Declares(index, position));
                }
                declares.push(vec![None; declarations.len()]);
            }
        }
    }

    let mut found: Vec<Declared> = asked.iter().map(|_| Declared::default()).collect();
    let answers = if requests.is_empty() { Vec::new() } else { rpc.batch(requests).await? };
    for (request, answer) in pending.into_iter().zip(answers) {
        match request {
            Pending::Description(index) => {
                if let Some(declared) = found.get_mut(index) {
                    declared.description = decode(&answer)?;
                }
            }
            Pending::Tags(index) => {
                let tags: Option<Vec<JsDocTag>> = decode(&answer)?;
                if let Some(declared) = found.get_mut(index) {
                    declared.tags = tags_of(tags.unwrap_or_default());
                }
            }
            Pending::Declares(index, position) => {
                let symbol: Option<SymbolInfo> = decode(&answer)?;
                if let Some(slot) = declares.get_mut(index).and_then(|slots| slots.get_mut(position)) {
                    *slot = symbol.map(|symbol| (symbol.parent, symbol.reference));
                }
            }
        }
    }

    let parents = parent_names(rpc, memo, &declares).await?;
    if parents.values().all(Option::is_none) {
        return Ok(found);
    }
    let files = memo.files.get_or_try_init(|| program_files(rpc)).await?;
    for ((declared, prop), slots) in found.iter_mut().zip(asked).zip(&declares) {
        let mut interfaces = prop.property.declarations.iter().zip(slots).map(|(declaration, slot)| {
            let name = slot.as_ref()?.0.as_ref().and_then(|parent| parents.get(parent).cloned().flatten())?;
            let file = declared_in(declaration);
            let file_name = files.get(file).cloned().unwrap_or_else(|| file.to_string());
            Some(PropParent { name, file_name })
        });
        // react-docgen-typescript's `parent`: the first declaration's, and only when an interface holds it.
        declared.parent = interfaces.next().flatten();
        declared.declarations = declared.parent.iter().cloned().chain(interfaces.flatten()).collect();
    }
    Ok(found)
}

/// The name of each parent `declares` names, when it is an interface: asked once per snapshot, in one round trip for
/// those not seen before.
async fn parent_names(
    rpc: &Rpc,
    memo: &Memo,
    declares: &[Vec<Option<(Option<CompactSymbol>, Value)>>],
) -> Result<FxHashMap<CompactSymbol, Option<String>>, CallError> {
    let mut known: FxHashMap<CompactSymbol, Option<String>> = FxHashMap::default();
    let mut unseen: Vec<(CompactSymbol, &Value)> = Vec::new();
    {
        let seen = memo.parents.lock().map_err(|_| CallError::Fatal("the parent memo is poisoned".to_string()))?;
        for (parent, reference) in declares.iter().flatten().flatten().filter_map(|(p, r)| Some((p.as_ref()?, r))) {
            if known.contains_key(parent) {
                continue;
            }
            match seen.get(parent) {
                Some(name) => {
                    known.insert(parent.clone(), name.clone());
                }
                None => {
                    known.insert(parent.clone(), None);
                    unseen.push((parent.clone(), reference));
                }
            }
        }
    }
    if unseen.is_empty() {
        return Ok(known);
    }
    let requests =
        unseen.iter().map(|(_, reference)| ("getParentOfSymbolForChecker", json!({ "symbol": reference }))).collect();
    let answers = rpc.batch(requests).await?;
    let mut seen = memo.parents.lock().map_err(|_| CallError::Fatal("the parent memo is poisoned".to_string()))?;
    for ((parent, _), answer) in unseen.into_iter().zip(answers) {
        let symbol: Option<SymbolInfo> = decode(&answer)?;
        let name = symbol.filter(|symbol| symbol.flags & flag::SYMBOL_INTERFACE != 0).map(|symbol| symbol.name);
        seen.insert(parent.clone(), name.clone());
        known.insert(parent, name);
    }
    Ok(known)
}

/// The program's files, by their own path and by its lower-cased form, the first file of a lower-cased form winning.
async fn program_files(rpc: &Rpc) -> Result<FxHashMap<String, String>, CallError> {
    let names = rpc.source_file_names().await?;
    let mut files = FxHashMap::default();
    for name in &names {
        files.insert(name.clone(), name.clone());
    }
    for name in names {
        files.entry(name.to_lowercase()).or_insert(name);
    }
    Ok(files)
}

/// A prop's tags as the structural pass keys them: by name, the last of a repeated tag winning, its text trimmed.
fn tags_of(tags: Vec<JsDocTag>) -> BTreeMap<String, String> {
    tags.into_iter().map(|tag| (tag.name, tag.text.unwrap_or_default().trim().to_string())).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tag(name: &str, text: Option<&str>) -> JsDocTag {
        JsDocTag { name: name.to_string(), text: text.map(str::to_string) }
    }

    #[test]
    fn a_tag_is_keyed_by_name_with_its_text_trimmed_and_a_repeated_tag_keeps_the_last() {
        let tags = tags_of(vec![
            tag("deprecated", None),
            tag("see", Some(" https://a.example ")),
            tag("since", Some("2.0")),
            tag("see", Some("https://b.example")),
        ]);

        assert_eq!(
