    }

    let mut found: Vec<Declared> = asked.iter().map(|_| Declared::default()).collect();
    let answers = if requests.is_empty() { Vec::new() } else { rpc.batch(requests).await? };
    for (request, answer) in pending.into_iter().zip(answers) {
        match request {
            Pending::Description(index) => {
                if let Some(declared) = found.get_mut(index) {
                    declared.description = decode(&answer)?;
