const [, , root, file, exportName, propName, configFile] = process.argv
const mod: any = await import('tsrs/sync')
const api = new mod.API({ cwd: root })
const client = (api as any).client
const req = (method: string, params: any) => client.apiRequest(method, params)
const { options } = configFile
  ? req('parseConfigFile', { file: configFile })
  : { options: { jsx: 1, module: 99, moduleResolution: 100, target: 9, strict: true, skipLibCheck: true, noEmit: true } }
const snap = req('createSnapshot', { createPrograms: [{ rootFiles: [file], compilerOptions: options }] })
const s = (method: string, params: any) => req(method, { snapshot: snap.snapshot, project: snap.projects[0].id, ...params })
const module = s('getSymbolOfSourceFile', { file })
let exported = s('getExportsOfModule', { symbol: module.reference }).find((e: any) => e.name === exportName)
if (exported.flags & 2097152) exported = s('getAliasedSymbol', { symbol: exported.reference })
const t = s('getTypeOfSymbol', { symbol: exported.reference })
const [sig] = s('getSignaturesOfType', { type: t.id, kind: 0 })
const [param] = s('getParametersOfSignature', { objectId: sig.id })
const props = s('getTypeOfSymbol', { symbol: param.reference })
const p = s('getPropertiesOfType', { type: props.id }).find((x: any) => x.name === propName)
console.log(JSON.stringify({ ...p, reference: undefined }))
for (const location of p.declarations ?? []) {
  const declared = s('getSymbolOfDeclarationForChecker', { location })
  console.log(' declares', location, JSON.stringify(declared && { ...declared, reference: undefined }))
  const parent = declared && s('getParentOfSymbolForChecker', { symbol: declared.reference })
  console.log('   parent', JSON.stringify(parent && { ...parent, reference: undefined }))
}
api.close()

