#[test]
fn parent_and_declarations_are_the_checkers_even_where_it_names_none() {
    let mut out = output();
    let outcome = SemanticOutcome {
        components: vec![button(vec![declared("label", Some("BaseProps"), &[]), declared("size", None, &[])])],
        ..Default::default()
    };

