// Throwaway spike (not committed): the facts capture over the construct suite.
import { join, relative } from 'node:path'
import { realpathSync } from 'node:fs'
import { API, SymbolFlags } from 'typescript-beta/sync'
import { SyntaxKind } from 'typescript-beta/ast'
import { exportAt, propsTypeOf } from './src/checker-components.ts'
import { listFixtures, PROP } from './src/construct-suite.ts'

const suite = realpathSync(join(import.meta.dirname, 'construct-suite'))
const fixtures = listFixtures(suite)
const api = new API({ cwd: suite })
const { options } = api.parseConfigFile(join(suite, 'tsconfig.json'))
const program = api.createProgram([...new Set(fixtures.map((f) => f.file))], options)
const { checker } = program.getProject()
let unions = 0
for (const fixture of fixtures) {
  const moduleSymbol = checker.getSymbolOfSourceFile(fixture.file)
  const exported = exportAt(checker, moduleSymbol, fixture.exportPath)
  const propsType = propsTypeOf(checker, exported)
  const prop = checker.getPropertyOfType(propsType, PROP)
  const node: any = prop.declarations?.[0]?.resolve()
  const parentNode = node?.parent
  const parent =
    parentNode?.kind === SyntaxKind.InterfaceDeclaration
      ? { name: parentNode.name.text, file: relative(suite, parentNode.getSourceFile().fileName) }
      : null
  let typeNode = node?.type
  if (typeNode?.kind === SyntaxKind.TypeReference) {
    const alias = checker.getSymbolAtLocation(typeNode.typeName)
    const declaration: any = alias && alias.flags & SymbolFlags.TypeAlias ? alias.declarations?.[0]?.resolve() : undefined
    if (declaration?.kind === SyntaxKind.TypeAliasDeclaration && declaration.typeParameters === undefined) typeNode = declaration.type
  }
  const order =
    typeNode?.kind === SyntaxKind.UnionType
      ? typeNode.types.map((member: any) => checker.typeToString(checker.getTypeFromTypeNode(member)))
      : null
  if (order) unions++
  const tags = checker.getJsDocTagsOfSymbol(prop)
  console.log(
    fixture.id,
    JSON.stringify({ parent, order, required: !(prop.flags & SymbolFlags.Optional), doc: checker.getDocumentationCommentOfSymbol(prop), tags }),
  )
}
console.error('unions', unions, 'of', fixtures.length)
program.dispose()
api.close()

